import{_ as l,a0 as o,w as d,s as c,I as i,x as s,a1 as a,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"cp 命令兩個高效的用法 | LCTT x X-CMD","titleTemplate":false,"description":"cp 命令兩個高效的用法 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"cp 命令兩個高效的用法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"cp 命令兩個高效的用法 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170705 Two great uses for the cp command","title":"cp 命令兩個高效的用法","tag":"201708","desc":""},"relativePath":"201708/20170705 Two great uses for the cp command.md","filePath":"[post].md"}'),r={name:"201708/20170705 Two great uses for the cp command.md"};function h(g,e,u,k,b,m){const t=o("Link");return d(),c("div",null,[e[22]||(e[22]=i("h1",{id:"cp-命令兩個高效的用法",tabindex:"-1"},[s("cp 命令兩個高效的用法 "),i("a",{class:"header-anchor",href:"#cp-命令兩個高效的用法","aria-label":"Permalink to “cp 命令兩個高效的用法”"},"​")],-1)),e[23]||(e[23]=i("blockquote",null,[i("p",null,"Linux 中高效的備份拷貝命令")],-1)),e[24]||(e[24]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/car-penguin-drive-linux-yellow.png?itok=ueZE5mph",alt:"Two great uses for the cp command",title:"Two great uses for the cp command"})],-1)),e[25]||(e[25]=i("p",null,[s("在 Linux 上能使用鼠標點來點去的圖形化界面是一件很美妙的事……但是如果你喜歡的開發交互環境和編譯器是終端窗口、Bash 和 Vim，那你應該像我一樣"),i("em",null,"經常"),s("和終端打交道。")],-1)),i("p",null,[e[2]||(e[2]=s("即使是不經常使用終端的人，如果對終端環境深入瞭解也能獲益良多。舉個例子—— ",-1)),e[3]||(e[3]=i("code",null,"cp",-1)),e[4]||(e[4]=s(" 命令，據 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Cp_(Unix)"},{default:p(()=>[...e[0]||(e[0]=[s("維基百科",-1)])]),_:1}),e[5]||(e[5]=s(" 的解釋，",-1)),e[6]||(e[6]=i("code",null,"cp",-1)),e[7]||(e[7]=s(" （意即 copy）命令是第一個版本的 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Unix"},{default:p(()=>[...e[1]||(e[1]=[s("Unix",-1)])]),_:1}),e[8]||(e[8]=n(" 系統的一部分。連同一組其它的命令 <code>ls</code>、<code>mv</code>、<code>cd</code>、<code>pwd</code>、<code>mkdir</code>、<code>vi</code>、<code>sh</code>、<code>sed</code> 和 <code>awk</code> ，還有提到的 <code>cp</code> 都是我在 1984 年接觸 System V Unix 系統時所學習的命令之一。<code>cp</code> 命令最常見的用法是製作文件副本。像這樣：",23))]),e[26]||(e[26]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp sourcefile destfile</span></span></code></pre></div><p>在終端中執行此命令，上述命令將名為 <code>sourcefile</code> 的文件複製到名為 <code>destfile</code> 的文件中。如果在執行命令之前 <code>destfile</code> 文件不存在，那將會創建此文件，如果已經存在，那就會覆蓋此文件。</p><p>這個命令我不知道自己用了多少次了（我也不想知道），但是我知道在我編寫測試代碼的時候，我經常用，為了保留當前正常的版本，而且又能繼續修改，我會輸入這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp test1.py test1.bak</span></span></code></pre></div><p>在過去的30多年裏，我使用了無數次這個命令。另外，當我決定編寫我的第二個版本的測試程序時，我會輸入這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp test1.py test2.py</span></span></code></pre></div><p>這樣就完成了修改程序的第一步。</p><p>我通常很少查看 <code>cp</code> 命令的參考文檔，但是當我在備份我的圖片文件夾的時候（在 GUI 環境下使用 “file” 應用），我開始思考“在 <code>cp</code> 命令中是否有個參數支持只複製新文件或者是修改過的文件。”果然，真的有！</p><h3 id="高效用法-1-更新你的文件夾" tabindex="-1">高效用法 1：更新你的文件夾 <a class="header-anchor" href="#高效用法-1-更新你的文件夾" aria-label="Permalink to “高效用法 1：更新你的文件夾”">​</a></h3><p>比如説在我的電腦上有一個存放各種文件的文件夾，另外我要不時的往裏面添加一些新文件，而且我會不時地修改一些文件，例如我手機裏下載的照片或者是音樂。</p><p>假設我收集的這些文件對我而言都很有價值，我有時候會想做個拷貝，就像是“快照”一樣將文件保存在其它媒體。當然目前有很多程序都支持備份，但是我想更為精確的將目錄結構複製到可移動設備中，方便於我經常使用這些離線設備或者連接到其它電腦上。</p><p><code>cp</code> 命令提供了一個易如反掌的方法。例子如下：</p><p>在我的 <code>Pictures</code> 文件夾下，我有這樣一個文件夾名字為 <code>Misc</code>。為了方便説明，我把文件拷貝到 USB 存儲設備上。讓我們開始吧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Pictures$ cp -r Misc /media/clh/4388-D5FE</span></span>
<span class="line"><span>me@desktop:~/Pictures$</span></span></code></pre></div><p>上面的命令是我從按照終端窗口中完整複製下來的。對於有些人來説不是很適應這種環境，在我們輸入命令或者執行命令之前，需要注意的是 <code>me@mydesktop:~/Pictures</code> 這個前綴，<code>me</code> 這個是當前用户，<code>mydesktop</code> 這是電腦名稱，<code>~/Pictures</code> 這個是當前工作目錄，是 <code>/home/me/Pictures</code> 完整路徑的縮寫。</p><p>我輸入這個命令 <code>cp -r Misc /media/clh/4388-D5FE</code> 並執行後 ，拷貝 <code>Misc</code> 目錄下所有文件（這個 <code>-r</code> 參數，全稱 “recursive”，遞歸處理，意思為本目錄下所有文件及子目錄一起處理）到我的 USB 設備的掛載目錄 <code>/media/clh/4388-D5FE</code>。</p><p>執行命令後回到之前的提示，大多數命令繼承了 Unix 的特性，在命令執行後，如果沒有任何異常什麼都不顯示，在任務結束之前不會顯示像 “execution succeeded” 這樣的提示消息。如果想獲取更多的反饋，就使用 <code>-v</code> 參數讓執行結果更詳細。</p><p>下圖中是我的 USB 設備中剛剛拷貝過來的文件夾 <code>Misc</code> ，裏面總共有 9 張圖片。</p><p><img src="https://opensource.com/sites/default/files/u128651/cp1_file_structure.png" alt="Image of the new copy of Misc on the USB drive" title="Image of the new copy of Misc on the USB drive"></p><p>假設我要在原始拷貝路徑下 <code>~/Pictures/Misc</code> 下添加一些新文件，就像這樣：</p><p><img src="https://opensource.com/sites/default/files/u128651/cp2_new_files.png" alt="New files added to the master directory" title="New files added to the master directory"></p><p>現在我想只拷貝新的文件到我的存儲設備上，我就使用 <code>cp</code> 的“更新”和“詳細”選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Pictures$ cp -r -u -v Misc /media/clh/4388-D5FE</span></span>
<span class="line"><span>&#39;Misc/asunder.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/asunder.png&#39;</span></span>
<span class="line"><span>&#39;Misc/editing tags guayadeque.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/editing tags guayadeque.png&#39;</span></span>
<span class="line"><span>&#39;Misc/misc on usb.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/misc on usb.png&#39;</span></span>
<span class="line"><span>me@desktop:~/Pictures$</span></span></code></pre></div><p>上面的第一行中是 <code>cp</code> 命令和具體的參數（<code>-r</code> 是“遞歸”， <code>-u</code> 是“更新”，<code>-v</code> 是“詳細”）。接下來的三行顯示被複制文件的信息，最後一行顯示命令列提示符。</p><p>通常來説，參數 <code>-r</code> 也可用更詳細的風格 <code>--recursive</code>。但是以簡短的方式，也可以這麼連用 <code>-ruv</code>。</p><h3 id="高效用法-2-版本備份" tabindex="-1">高效用法 2：版本備份 <a class="header-anchor" href="#高效用法-2-版本備份" aria-label="Permalink to “高效用法 2：版本備份”">​</a></h3><p>回到一開始的例子中，我在開發的時候定期給我的代碼版本進行備份。然後我找到了另一種更好用的 <code>cp</code> 參數。</p><p>假設我正在編寫一個非常有用的 Python 程序，作為一個喜歡不斷修改代碼的開發者，我會在一開始編寫一個程序簡單版本，然後不停的往裏面添加各種功能直到它能成功的運行起來。比方説我的第一個版本就是用 Python 程序打印出 “hello world”。這隻有一行代碼的程序就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print &#39;hello world&#39;</span></span></code></pre></div><p>然後我將這個代碼保存成文件命名為 <code>test1.py</code>。我可以這麼運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Test$ python test1.py</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>me@desktop:~/Test$</span></span></code></pre></div><p>現在程序可以運行了，我想在添加新的內容之前進行備份。我決定使用帶編號的備份選項，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clh@vancouver:~/Test$ cp --force --backup=numbered test1.py test1.py</span></span>
<span class="line"><span>clh@vancouver:~/Test$ ls</span></span>
<span class="line"><span>test1.py  test1.py.~1~</span></span>
<span class="line"><span>clh@vancouver:~/Test$</span></span></code></pre></div><p>所以，上面的做法是什麼意思呢？</p><p>第一，這個 <code>--backup=numbered</code> 參數意思為“我要做個備份，而且是帶編號的連續備份”。所以一個備份就是 1 號，第二個就是 2 號，等等。</p><p>第二，如果源文件和目標文件名字是一樣的。通常我們使用 <code>cp</code> 命令去拷貝成自己，會得到這樣的報錯信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp: &#39;test1.py&#39; and &#39;test1.py&#39; are the same file</span></span></code></pre></div><p>在特殊情況下，如果我們想備份的源文件和目標文件名字相同，我們使用 <code>--force</code> 參數。</p><p>第三，我使用 <code>ls</code> （意即 “list”）命令來顯示現在目錄下的文件，名字為 <code>test1.py</code> 的是原始文件，名字為 <code>test1.py.~1~</code> 的是備份文件</p><p>假如現在我要加上第二個功能，在程序里加上另一行代碼，可以打印 “Kilroy was here.”。現在程序文件 <code>test1.py</code> 的內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print &#39;hello world&#39;</span></span>
<span class="line"><span>print &#39;Kilroy was here&#39;</span></span></code></pre></div><p>看到 Python 編程多麼簡單了嗎？不管怎樣，如果我再次執行備份的步驟，結果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clh@vancouver:~/Test$ cp --force --backup=numbered test1.py test1.py</span></span>
<span class="line"><span>clh@vancouver:~/Test$ ls</span></span>
<span class="line"><span>test1.py test1.py.~1~ test1.py.~2~</span></span>
<span class="line"><span>clh@vancouver:~/Test$</span></span></code></pre></div><p>現在我有有兩個備份文件： <code>test1.py.~1~</code> 包含了一行代碼的程序，和 <code>test1.py.~2~</code> 包含兩行代碼的程序。</p><p>這個很好用的功能，我考慮做個 shell 函數讓它變得更簡單。</p><h3 id="最後總結" tabindex="-1">最後總結 <a class="header-anchor" href="#最後總結" aria-label="Permalink to “最後總結”">​</a></h3><p>第一，Linux 手冊頁，它在大多數桌面和服務器發行版都默認安裝了，它提供了更為詳細的使用方法和例子，對於 <code>cp</code> 命令，在終端中輸入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man cp</span></span></code></pre></div><p>對於那些想學習如何使用這些命令，但不清楚如何使用的用户應該首先看一下這些説明，然後我建議創建一個測試目錄和文件來嘗試使用命令和選項。</p><p>第二，興趣是最好的老師。在你最喜歡的搜索引擎中搜索 “linux shell tutorial”，你會獲得很多有趣和有用的資源。</p><p>第三，你是不是在想，“為什麼我要用這麼麻煩的方法，圖形化界面中有相同的功能，只用點擊幾下豈不是更簡單？”，關於這個問題我有兩個理由。首先，在我們工作中需要中斷其他工作流程以及大量使用點擊動作時，點擊動作可就不簡單了。其次，如果我們要完成流水線般的重複性工作，通過使用 shell 腳本和 shell 函數以及 shell 重命名等功能就能很輕鬆的實現。</p><p>你還知道關於 <code>cp</code> 命令其他更棒的使用方式嗎？請在留言中積極回覆哦～</p><p>（題圖：Opensource.com）</p><hr><p>作者簡介：</p><p>Chris Hermansen - 1978 年畢業於英國哥倫比亞大學後一直從事計算機相關職業，我從 2005 年開始一直使用 Linux、Solaris、SunOS，在那之前我就是 Unix 系統管理員了，在技術方面，我的大量的職業生涯都是在做數據分析，尤其是空間數據分析，我有大量的編程經驗與數據分析經驗，熟練使用 awk、Python、PostgreSQL、PostGIS 和 Groovy。</p><hr>`,57)),i("p",null,[e[10]||(e[10]=s("via: ",-1)),a(t,{href:"https://opensource.com/article/17/7/two-great-uses-cp-command"},{default:p(()=>[...e[9]||(e[9]=[s("https://opensource.com/article/17/7/two-great-uses-cp-command",-1)])]),_:1})]),i("p",null,[e[14]||(e[14]=s("作者：",-1)),a(t,{href:"https://opensource.com/users/clhermansen"},{default:p(()=>[...e[11]||(e[11]=[s("Chris Hermansen",-1)])]),_:1}),e[15]||(e[15]=s(" 譯者：",-1)),a(t,{href:"https://github.com/bigdimple"},{default:p(()=>[...e[12]||(e[12]=[s("bigdimple",-1)])]),_:1}),e[16]||(e[16]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[13]||(e[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[19]||(e[19]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[s("LCTT",-1)])]),_:1}),e[20]||(e[20]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[s("Linux中國",-1)])]),_:1}),e[21]||(e[21]=s(" 榮譽推出",-1))])])}const C=l(r,[["render",h]]);export{v as __pageData,C as default};
